package io.github.samlinb.openbone.core;

import java.util.*;
import io.github.samlinb.openbone.application.*;
import io.github.samlinb.openbone.core.animation.*;
import io.github.samlinb.openbone.core.math.*;
import io.github.samlinb.openbone.core.model.*;
import io.github.samlinb.openbone.io.*;
import org.junit.jupiter.api.*;
import static io.github.samlinb.openbone.TestData.id;
import static org.junit.jupiter.api.Assertions.*;

class ConstraintTimelineTest {
 static final EntityId CLIP=AnimationClip.DEFAULT_ID;
 static DocumentSnapshot base(){return new DocumentSnapshot(List.of(new Bone(id(1),"root",null,Transform.IDENTITY,0),new Bone(id(2),"arm",id(1),Transform.IDENTITY,100),new Bone(id(3),"target",id(1),new Transform(0,100,0,1,1),0)),List.of(),List.of());}
 static DocumentSnapshot ik(){return base().withConstraints(List.of(new IkConstraint(id(5),"ik",0,true,List.of(id(2)),id(3),0,0,true,false,false,false)));}
 static DocumentSnapshot put(DocumentSnapshot d,ConstraintChannel c,double t,Double... v){return AnimationEdits.putConstraint(d,CLIP,id(5),c,t,List.of(v));}
 static List<Double> sample(DocumentSnapshot d,ConstraintChannel c,double t){return c.values(AnimationSampler.constraints(d,CLIP,t,false).get(0));}
 @Test void ikAbsoluteMixAnalyticEndpointBooleanStepAndSetupUnchanged(){
  var setup=ik();var d=put(setup,ConstraintChannel.IK,.25,0.,0.,1.,0.,0.);d=put(d,ConstraintChannel.IK,1.25,1.,0.,0.,1.,1.);
  assertEquals(List.of(0.,0.,1.,0.,0.),sample(d,ConstraintChannel.IK,0));assertEquals(List.of(.5,0.,1.,0.,0.),sample(d,ConstraintChannel.IK,.75));assertEquals(List.of(1.,0.,0.,1.,1.),sample(d,ConstraintChannel.IK,1.25));
  var w=AnimationSampler.world(d,CLIP,.75,false).bones().get(id(2));assertEquals(Math.sqrt(.5),w.matrix().a(),1e-12);assertEquals(100*Math.sqrt(.5),w.tip().y(),1e-9);assertEquals(setup.bones(),d.bones());assertEquals(setup.constraints(),d.constraints());
  assertEquals(AnimationSampler.world(d,CLIP,.5,false),AnimationSampler.world(d,CLIP,1.75,true));
 }
 @Test void transformSixIndependentCurvesAndExactKeys(){
  var d=base().withConstraints(List.of(new TransformConstraint(id(5),"transform",0,true,List.of(id(2)),id(3),false,false,Collections.nCopies(6,0.),List.of(0.,0.,0.,0.,0.,0.))));
  d=put(d,ConstraintChannel.TRANSFORM_MIX,0,0.,0.,0.,0.,0.,0.);d=put(d,ConstraintChannel.TRANSFORM_MIX,1,1.,1.,1.,1.,1.,1.);var first=d.animation(CLIP).keys().get(0);var bezier=new Curve(Curve.Kind.BEZIER,.2,0,.8,1);d=AnimationEdits.curves(d,CLIP,Set.of(first.id()),List.of(bezier,Curve.STEPPED,Curve.LINEAR,Curve.LINEAR,Curve.LINEAR,Curve.STEPPED));
  assertEquals(List.of(bezier.progress(.25),0.,.25,.25,.25,0.),sample(d,ConstraintChannel.TRANSFORM_MIX,.25));assertEquals(25,AnimationSampler.world(d,CLIP,.25,false).bones().get(id(2)).origin().y(),1e-9);assertEquals(Collections.nCopies(6,1.),sample(d,ConstraintChannel.TRANSFORM_MIX,1));
 }
 @Test void pathThreeGroupsComposeAndPreserveOwnVersionFive()throws Exception{
  var slot=new Slot(id(4),"path-slot",id(1),null);var d=new DocumentSnapshot(base().bones(),List.of(slot),List.of()).withConstraints(List.of(new PathConstraint(id(5),"path",0,true,List.of(id(2)),id(4),PathConstraint.PositionMode.FIXED,PathConstraint.SpacingMode.FIXED,PathConstraint.RotateMode.TANGENT,10,20,0,1,1,1)));
  d=put(d,ConstraintChannel.PATH_POSITION,0,30.);d=put(d,ConstraintChannel.PATH_POSITION,2,50.);d=put(d,ConstraintChannel.PATH_SPACING,0,12.);d=put(d,ConstraintChannel.PATH_MIX,0,.1,.2,.3);var p=(PathConstraint)AnimationSampler.constraints(d,CLIP,1,false).get(0);assertEquals(40,p.position());assertEquals(12,p.spacing());assertEquals(.3,p.mixY());var codec=new ProjectCodec();var bytes=codec.encode(d);assertTrue(new String(bytes,java.nio.charset.StandardCharsets.UTF_8).contains("\"schemaVersion\" : 5"));assertEquals(d,codec.decode(bytes));assertEquals(2,d.animation(CLIP).duration());
 }
 @Test void exactReplaceMoveCopyPasteCollisionDeleteAndCurvesPreserveIdentity(){
  var d=put(ik(),ConstraintChannel.IK,0,.2,0.,1.,0.,0.);var first=d.animation(CLIP).keys().get(0).id();d=put(d,ConstraintChannel.IK,0,.3,0.,0.,1.,0.);assertEquals(first,d.animation(CLIP).keys().get(0).id());var clip=AnimationEdits.copy(d,CLIP,Set.of(first));d=AnimationEdits.paste(d,CLIP,clip,1);var last=d.animation(CLIP).keys().get(1).id();assertNotEquals(first,last);var stable=d;assertThrows(IllegalArgumentException.class,()->AnimationEdits.paste(stable,CLIP,clip,1));assertThrows(IllegalArgumentException.class,()->AnimationEdits.move(stable,CLIP,Set.of(last),-1));d=AnimationEdits.curves(d,CLIP,Set.of(first),List.of(Curve.LINEAR));assertEquals(Curve.STEPPED,d.animation(CLIP).keys().get(0).curves().get(2));d=AnimationEdits.move(d,CLIP,Set.of(last),.5);assertEquals(1.5,d.animation(CLIP).duration());d=AnimationEdits.remove(d,CLIP,Set.of(first,last));assertTrue(d.animation(CLIP).constraintTracks().isEmpty());
 }
 @Test void trsAndDeformEditsPreserveConstraintTracksAndDeletingTargetCascades(){
  var d=put(ik(),ConstraintChannel.IK,0,.5,0.,1.,0.,0.);var constraintTracks=d.animation(CLIP).constraintTracks();d=AnimationEdits.put(d,CLIP,id(1),Channel.TRANSLATE,1,List.of(3.,4.));assertEquals(constraintTracks,d.animation(CLIP).constraintTracks());var boneKey=d.animation(CLIP).timelines().get(0).keys().get(0).id();d=AnimationEdits.move(d,CLIP,Set.of(boneKey),1);assertEquals(constraintTracks,d.animation(CLIP).constraintTracks());var deleted=ModelEdits.delete(d,id(3));assertTrue(deleted.constraints().isEmpty());assertTrue(deleted.animation(CLIP).constraintTracks().isEmpty());assertEquals(1,deleted.animation(CLIP).timelines().size());
 }
 @Test void illegalBooleanCurveReferenceTypeDuplicateAndControlHullRejectBeforePublication(){
  var d=put(ik(),ConstraintChannel.IK,0,0.,0.,1.,0.,0.);d=put(d,ConstraintChannel.IK,1,1.,0.,0.,0.,0.);var stable=d;var first=d.animation(CLIP).keys().get(0).id();assertThrows(IllegalArgumentException.class,()->AnimationEdits.curves(stable,CLIP,Set.of(first),List.of(new Curve(Curve.Kind.BEZIER,.2,2,.8,2))));assertThrows(IllegalArgumentException.class,()->put(stable,ConstraintChannel.IK,2,.5,0.,.5,0.,0.));assertThrows(IllegalArgumentException.class,()->put(stable,ConstraintChannel.PATH_POSITION,2,1.));var key=new Keyframe(id(20),0,List.of(.5,0.,1.,0.,0.),Collections.nCopies(5,Curve.LINEAR));assertThrows(IllegalArgumentException.class,()->new ConstraintTimeline(id(5),ConstraintChannel.IK,List.of(key)));var track=d.animation(CLIP).constraintTracks().get(0);assertThrows(IllegalArgumentException.class,()->new AnimationClip(CLIP,"dup",List.of(),List.of(),List.of(track,track)));var other=new ConstraintTimeline(id(30),track.channel(),track.keys());assertThrows(IllegalArgumentException.class,()->stable.withAnimations(List.of(new AnimationClip(CLIP,"missing",List.of(),List.of(),List.of(other)))));
 }
 @Test void runtimeRefusesPendingContinuousProofAndOldSchemaFourRoundtrips()throws Exception{var codec=new ProjectCodec();var old=ik();assertEquals(old,codec.decode(codec.encode(old)));var d=put(put(old,ConstraintChannel.IK,0,0.,0.,1.,0.,0.),ConstraintChannel.IK,1,1.,0.,1.,0.,0.);assertTrue(assertThrows(ProjectFormatException.class,()->RuntimeRange.validate(d)).getMessage().contains("constraintTracks"));}
 @Test void deformEditsCopyAndKeyIdentityDoNotDropConstraintTracks()throws Exception{
  var points=List.of(new Vec2(0,0),new Vec2(10,0),new Vec2(0,10));var mesh=new MeshAttachment(id(7),"mesh",id(6),"image.png",points,List.of(new Vec2(0,0),new Vec2(1,0),new Vec2(0,1)),3,List.of(0,1,2));var d=ik();d=new DocumentSnapshot(d.bones(),List.of(new Slot(id(6),"slot",id(2),id(7))),List.of(mesh),d.animations(),d.constraints());d=put(d,ConstraintChannel.IK,0,.5,0.,1.,0.,0.);var constraints=d.animation(CLIP).constraintTracks();d=DeformEdits.put(d,CLIP,id(7),0,List.of(0.,0.,1.,2.,0.,0.));assertEquals(constraints,d.animation(CLIP).constraintTracks());var keys=new HashSet<EntityId>();d.animation(CLIP).keys().forEach(k->keys.add(k.id()));var copied=AnimationEdits.copy(d,CLIP,keys);d=AnimationEdits.paste(d,CLIP,copied,1);assertEquals(2,d.animation(CLIP).deforms().get(0).keys().size());assertEquals(2,d.animation(CLIP).constraintTracks().get(0).keys().size());assertEquals(4,d.animation(CLIP).keys().stream().map(Keyframe::id).distinct().count());assertEquals(d,new ProjectCodec().decode(new ProjectCodec().encode(d)));
 }
 @Test void historyUndoRedoPreviewAndFailedCommandPreserveSelectionAndDirty(){
  var d=put(ik(),ConstraintChannel.IK,0,.5,0.,1.,0.,0.);var key=d.animation(CLIP).keys().get(0).id();var history=new CommandHistory(d);history.select(Selection.of(id(5)));history.selectKeys(Set.of(key));var before=history.state();history.beginPreview("移动约束关键帧");history.updatePreview(Commands.model(m->AnimationEdits.move(m,CLIP,Set.of(key),.5)));history.cancelPreview();assertEquals(before,history.state());assertEquals(0,history.undoCount());assertFalse(history.isDirty());history.execute("移动约束关键帧",Commands.model(m->AnimationEdits.move(m,CLIP,Set.of(key),.5)));assertEquals(Set.of(key),history.state().keySelection());assertEquals(1,history.undoCount());history.undo();assertEquals(before,history.state());assertFalse(history.isDirty());history.redo();var valid=history.state();assertThrows(IllegalArgumentException.class,()->history.execute("非法关键帧",Commands.model(m->AnimationEdits.putConstraint(m,CLIP,id(5),ConstraintChannel.IK,1,List.of(2.,0.,1.,0.,0.)))));assertEquals(valid,history.state());assertEquals(1,history.undoCount());history.execute("删除约束",Commands.model(m->ModelEdits.delete(m,id(5))));assertTrue(history.state().keySelection().isEmpty());history.undo();assertEquals(valid,history.state());
 }
 @Test void physicsReplayConsumesAnimatedUpstreamConstraintBeforeInertia(){
  var d=ik();var bones=new ArrayList<>(d.bones());bones.add(new Bone(id(4),"physical",id(2),new Transform(100,0,0,1,1),20));var physics=new PhysicsConstraint(id(6),"physics",1,true,id(4),List.of(1.,0.,0.,0.,0.),5000,List.of(1.,0.,1.,1.,0.,0.,1.));d=new DocumentSnapshot(bones,d.slots(),d.attachments(),d.animations(),List.of(d.constraint(id(5)),physics));d=put(d,ConstraintChannel.IK,0,0.,0.,1.,0.,0.);d=put(d,ConstraintChannel.IK,1,1.,0.,1.,0.,0.);var player=new PhysicsPlayer();var pose=player.seek(d,CLIP,1./60,false);double x=100*Math.cos(Math.PI/120);assertEquals(100-x,player.states().get(id(6)).xOffset(),1e-9);assertEquals(100,pose.bones().get(id(4)).origin().x(),1e-9);assertEquals(pose,new PhysicsPlayer().seek(d,CLIP,1./60,false));
 }
 @Test void ownMalformedNewFieldsRejectRatherThanLosingTracks()throws Exception{
  var codec=new ProjectCodec();var d=put(ik(),ConstraintChannel.IK,1,1.,0.,1.,0.,0.);var mapper=new com.fasterxml.jackson.databind.ObjectMapper();byte[] bytes=codec.encode(d);for(String mutation:List.of("oldVersion","unknown","missing","wrongChannel","badBoolean","nonStepped")){var root=mapper.readTree(bytes);var anim=(com.fasterxml.jackson.databind.node.ObjectNode)root.path("animations").get(0);var track=(com.fasterxml.jackson.databind.node.ObjectNode)anim.path("constraintTracks").get(0);var key=(com.fasterxml.jackson.databind.node.ObjectNode)track.path("keys").get(0);switch(mutation){case "oldVersion"->((com.fasterxml.jackson.databind.node.ObjectNode)root).put("schemaVersion",4);case "unknown"->track.put("future",true);case "missing"->track.remove("constraintId");case "wrongChannel"->track.put("channel","PHYSICS_UNKNOWN");case "badBoolean"->((com.fasterxml.jackson.databind.node.ArrayNode)key.path("values")).set(2,mapper.getNodeFactory().numberNode(.5));case "nonStepped"->((com.fasterxml.jackson.databind.node.ObjectNode)key.path("curves").get(2)).put("kind","LINEAR");}assertThrows(ProjectFormatException.class,()->codec.decode(mapper.writeValueAsBytes(root)),mutation);}}
}
